impl BlockSimulator {
    pub fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L, Run(I, 5)],
            right_tape: vec![R],
            state: HigherState::Right,
            base_steps: 32,
            self_steps: 0,
        }
    }

    pub fn try_dividing_shift_step(&mut self) -> Option<Exp> {
        use HigherState::*;
        use BlockSymbol::*;
        use RunSymbolType::*;
        // I I < -> < I I
        if self.state == Left && let [.., Run(I, n0 @ 2u128..)] = self.left_tape.as_slice() {
            let n = n0 / 2;
            decrease_run_by(&mut self.left_tape, I, n * 2);
            add_or_merge_run(&mut self.right_tape, I, n * 2);
            Some(n * 2)
        } else {
            None
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if let Some(new_base_steps) = self.try_dividing_shift_step() {
            self.base_steps += new_base_steps;
            self.self_steps += 1;
            return Ok(());
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps += new_base_steps;
        self.self_steps += 1;
        Ok(())
    }
}

